window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[36]={"3600":{"example:3600:exzh":"He uses a fake name.","example:3600:exzh2":"An account registered under a fake name.","example:3600:exzh3":"Using a fake name is illegal.","example:3600:exzh4":"I don't know her real name, only her fake one.","example:3600:exzh5":"Please don't write a fake name on this document."},"3601":{"example:3601:exzh":"I saw a display at the museum.","example:3601:exzh2":"I plan to attend the exhibition.","example:3601:exzh3":"A display of the new product was held.","example:3601:exzh4":"His work is on display.","example:3601:exzh5":"I'll help prepare the display."},"3602":{"example:3602:exzh":"Evaluation will be done according to this standard.","example:3602:exzh2":"The safety standards have been revised.","example:3602:exzh3":"You need to meet the standards.","example:3602:exzh4":"We set new standards.","example:3602:exzh5":"This data is based on the standard."},"3603":{"example:3603:exzh":"The station in the south is crowded.","example:3603:exzh2":"The climate in the south is warm.","example:3603:exzh3":"He is from the south.","example:3603:exzh4":"The south has beautiful seas.","example:3603:exzh5":"I'll take part in an event in the south."},"3604":{"example:3604:exzh":"He fell into danger.","example:3604:exzh2":"We easily fall into the same mistakes.","example:3604:exzh3":"He has fallen into serious anxiety.","example:3604:exzh4":"Be careful not to get into trouble.","example:3604:exzh5":"I ended up in that situation without meaning to."},"3605":{"example:3605:exzh":"Common sense is important.","example:3605:exzh2":"He has no common sense.","example:3605:exzh3":"Start by questioning common sense.","example:3605:exzh4":"Let's build up our common sense.","example:3605:exzh5":"I learned common sense at school."},"3606":{"example:3606:exzh":"I accomplished my goal.","example:3606:exzh2":"If you work hard, you can accomplish it.","example:3606:exzh3":"Accomplishing the plan is hard.","example:3606:exzh4":"He accomplished his dream.","example:3606:exzh5":"I will accomplish this project."},"3608":{"example:3608:exzh":"This box is very solid.","example:3608:exzh2":"It's important to keep a firm promise.","example:3608:exzh3":"I want to build a firm friendship.","example:3608:exzh4":"This garment is made of stiff material.","example:3608:exzh5":"Flowers don't grow easily in hard ground."},"3609":{"example:3609:exzh":"The price of this product is high.","example:3609:exzh2":"He checked the amount.","example:3609:exzh3":"Paying the amount was a hassle.","example:3609:exzh4":"If there's a promotion, the price goes down.","example:3609:exzh5":"Is this amount correct?"},"3610":{"example:3610:exzh":"Anesthesia is administered for the surgery.","example:3610:exzh2":"Anesthesia is used to ease pain.","example:3610:exzh3":"It takes some time to wake up from anesthesia.","example:3610:exzh4":"He is groggy from the effects of the anesthesia.","example:3610:exzh5":"The effect varies depending on the type of anesthesia."},"3611":{"example:3611:exzh":"It was supposed to end much earlier.","example:3611:exzh2":"Please don't forget the original purpose.","example:3611:exzh3":"He has outstanding talent by nature.","example:3611:exzh4":"The original plan has been changed.","example:3611:exzh5":"I want to get back to how I used to be."},"3612":{"example:3612:exzh":"He turned down that proposal.","example:3612:exzh2":"It's important to give a proper refusal.","example:3612:exzh3":"Thank you for understanding my refusal.","example:3612:exzh4":"Sometimes it's hard to tell someone you're declining.","example:3612:exzh5":"If you need to refuse, say so honestly."},"3615":{"example:3615:exzh":"I want to go to Canada.","example:3615:exzh2":"Canadian culture is interesting.","example:3615:exzh3":"Canada is a big country.","example:3615:exzh4":"I traveled to Canada in the summer.","example:3615:exzh5":"I really love Canadian food.","grammar:3615:ex:trans":"I want to go to Canada.","grammar:3615:ex:structure":"nounに＋行きたい。 「〜に行きたい」 means want to go to…","grammar:3615:ex:explain":"This sentence practices the desire pattern 「〜たい」: attach 「たい」 to the stem of the masu-form (行き) to say that the speaker wants to do something, e.g. 「行きたい」 = want to go. 「〜たい」 conjugates like an i-adjective, so you can also say 「行きたくない」 and 「行きたかった」. The destination is marked with 「に」: 「カナダに行く」. Note that 「たい」 is used only for the speaker's own wishes; to say someone else wants to go, Japanese uses 「〜たがっている」. The subject is omitted and defaults to I wanting to go to Canada.","grammar:3615:ex:words:0:zh":"Canada","grammar:3615:ex:words:0:note":"loanword","grammar:3615:ex:words:0:pos":"noun","grammar:3615:ex:words:1:zh":"(destination)","grammar:3615:ex:words:1:pos":"particle","grammar:3615:ex:words:2:zh":"want to go","grammar:3615:ex:words:2:note":"ikitai；〜たい expresses desire","grammar:3615:ex:words:2:pos":"verb","grammar:3615:ex:points:0":"〜に行きたい：want to go to…","grammar:3615:ex:points:1":"〜たい: want to …","grammar:3615:ex2:trans":"Canadian culture is interesting.","grammar:3615:ex2:structure":"〔カナダの文化〕＋は＋i-adjective。","grammar:3615:ex2:words:0:zh":"Canada","grammar:3615:ex2:words:0:note":"loanword","grammar:3615:ex2:words:0:pos":"noun","grammar:3615:ex2:words:1:zh":"'s","grammar:3615:ex2:words:1:pos":"particle","grammar:3615:ex2:words:2:zh":"culture","grammar:3615:ex2:words:2:note":"ぶんか","grammar:3615:ex2:words:2:pos":"noun","grammar:3615:ex2:words:3:zh":"(topic marker)","grammar:3615:ex2:words:3:pos":"particle","grammar:3615:ex2:words:4:zh":"interesting","grammar:3615:ex2:words:4:note":"おもしろい","grammar:3615:ex2:words:4:pos":"adjective","grammar:3615:ex2:points:0":"カナダの文化: Canadian culture","grammar:3615:ex2:points:1":"面白い: interesting","grammar:3615:ex3:trans":"Canada is a big country.","grammar:3615:ex3:structure":"noun は＋i-adjective＋noun＋です.","grammar:3615:ex3:words:0:zh":"Canada","grammar:3615:ex3:words:0:note":"loanword","grammar:3615:ex3:words:0:pos":"noun","grammar:3615:ex3:words:1:zh":"(topic marker)","grammar:3615:ex3:words:1:pos":"particle","grammar:3615:ex3:words:2:zh":"vast","grammar:3615:ex3:words:2:note":"ひろい","grammar:3615:ex3:words:2:pos":"adjective","grammar:3615:ex3:words:3:zh":"country","grammar:3615:ex3:words:3:note":"くに","grammar:3615:ex3:words:3:pos":"noun","grammar:3615:ex3:words:4:zh":"is","grammar:3615:ex3:words:4:pos":"copula","grammar:3615:ex3:points:0":"広い国: a vast country","grammar:3615:ex3:points:1":"広い: wide, spacious","grammar:3615:ex4:trans":"I traveled to Canada in the summer.","grammar:3615:ex4:structure":"timeに＋placeに＋旅行した。 「〜に旅行する」 means to travel to…","grammar:3615:ex4:words:0:zh":"summer","grammar:3615:ex4:words:0:note":"なつ","grammar:3615:ex4:words:0:pos":"noun","grammar:3615:ex4:words:1:zh":"(point in time)","grammar:3615:ex4:words:1:pos":"particle","grammar:3615:ex4:words:2:zh":"Canada","grammar:3615:ex4:words:2:note":"loanword","grammar:3615:ex4:words:2:pos":"noun","grammar:3615:ex4:words:3:zh":"(destination)","grammar:3615:ex4:words:3:pos":"particle","grammar:3615:ex4:words:4:zh":"traveled","grammar:3615:ex4:words:4:note":"りょこうした","grammar:3615:ex4:words:4:pos":"verb","grammar:3615:ex4:points:0":"〜に旅行する: to travel to…","grammar:3615:ex4:points:1":"夏に: in the summer","grammar:3615:ex5:trans":"I love Canadian food.","grammar:3615:ex5:structure":"〔カナダの食べ物〕＋が＋大好きです。","grammar:3615:ex5:words:0:zh":"Canada","grammar:3615:ex5:words:0:note":"loanword","grammar:3615:ex5:words:0:pos":"noun","grammar:3615:ex5:words:1:zh":"'s","grammar:3615:ex5:words:1:pos":"particle","grammar:3615:ex5:words:2:zh":"food","grammar:3615:ex5:words:2:note":"たべもの","grammar:3615:ex5:words:2:pos":"noun","grammar:3615:ex5:words:3:zh":"(object marker)","grammar:3615:ex5:words:3:pos":"particle","grammar:3615:ex5:words:4:zh":"love","grammar:3615:ex5:words:4:note":"だいすき","grammar:3615:ex5:words:4:pos":"na-adjective","grammar:3615:ex5:words:5:zh":"(polite form)","grammar:3615:ex5:words:5:pos":"copula","grammar:3615:ex5:points:0":"〜が大好きです: to love …","grammar:3615:ex5:points:1":"カナダの食べ物: Canadian food"},"3616":{"example:3616:exzh":"I put one plate on top of another plate.","example:3616:exzh2":"This plate is stylish.","example:3616:exzh3":"Serve the food on a plate.","example:3616:exzh4":"I bought a new plate.","example:3616:exzh5":"Washing the dishes is a hassle.","grammar:3616:ex:trans":"I put the small dish on the plate.","grammar:3616:ex:structure":"〔お皿の上〕＋に、皿を＋置いた。「〜の上に〜を置く」 = to put … on top of …. 「皿」 = plate.","grammar:3616:ex:explain":"This sentence practices the position-plus-placement pattern 「〜の上に〜を置く」. 「〜の上に」 uses 「に」 to mark where the thing ends up (the place you put it), 「皿を」 uses 「を」 for the thing being placed, and the verb 「置く」 = to put. So 「お皿の上に皿を置いた」 = I put the small dish on the plate. The ta-form 「置いた」 is past, with the カ sound change (く → いた). In this sentence 「お皿」 carries the beautifying prefix 「お」, while the later 「皿（さら）」 is the plain word; they are actually the same word, and the context tells the larger plate from the smaller dish.","grammar:3616:ex:words:0:zh":"dish","grammar:3616:ex:words:0:note":"おさら","grammar:3616:ex:words:0:pos":"noun","grammar:3616:ex:words:1:zh":"'s","grammar:3616:ex:words:1:pos":"particle","grammar:3616:ex:words:2:zh":"go up","grammar:3616:ex:words:2:note":"うえ","grammar:3616:ex:words:2:pos":"noun","grammar:3616:ex:words:3:zh":"(the destination)","grammar:3616:ex:words:3:pos":"particle","grammar:3616:ex:words:4:zh":"small dish","grammar:3616:ex:words:4:note":"さら","grammar:3616:ex:words:4:pos":"noun","grammar:3616:ex:words:5:zh":"(object marker)","grammar:3616:ex:words:5:pos":"particle","grammar:3616:ex:words:6:zh":"put (past)","grammar:3616:ex:words:6:note":"おいた","grammar:3616:ex:words:6:pos":"verb","grammar:3616:ex:points:0":"皿（さら）: plate, dish","grammar:3616:ex:points:1":"〜の上に〜を置く: put… on top of…","grammar:3616:ex2:trans":"This plate is stylish.","grammar:3616:ex2:structure":"この＋皿＋は、おしゃれです。「おしゃれ」 = stylish, particular about appearance.","grammar:3616:ex2:words:0:zh":"this","grammar:3616:ex2:words:0:pos":"pre-noun adjectival","grammar:3616:ex2:words:1:zh":"dish","grammar:3616:ex2:words:1:note":"さら","grammar:3616:ex2:words:1:pos":"noun","grammar:3616:ex2:words:2:zh":"(topic marker)","grammar:3616:ex2:words:2:pos":"particle","grammar:3616:ex2:words:3:zh":"stylish","grammar:3616:ex2:words:3:note":"stylish","grammar:3616:ex2:words:3:pos":"na-adjective","grammar:3616:ex2:words:4:zh":"(polite form)","grammar:3616:ex2:words:4:pos":"copula","grammar:3616:ex2:points:0":"おしゃれ: stylish, particular about one's appearance","grammar:3616:ex2:points:1":"この皿: this plate","grammar:3616:ex3:trans":"Serve the food onto a plate.","grammar:3616:ex3:structure":"料理を、皿に＋盛る。 「〜に盛る」 means to serve onto…","grammar:3616:ex3:words:0:zh":"dish","grammar:3616:ex3:words:0:note":"りょうり","grammar:3616:ex3:words:0:pos":"noun","grammar:3616:ex3:words:1:zh":"(object marker)","grammar:3616:ex3:words:1:pos":"particle","grammar:3616:ex3:words:2:zh":"dish","grammar:3616:ex3:words:2:note":"さら","grammar:3616:ex3:words:2:pos":"noun","grammar:3616:ex3:words:3:zh":"(the destination)","grammar:3616:ex3:words:3:pos":"particle","grammar:3616:ex3:words:4:zh":"to serve / to dish up","grammar:3616:ex3:words:4:note":"もる","grammar:3616:ex3:words:4:pos":"verb","grammar:3616:ex3:points:0":"〜に盛る: to serve onto… (皿に盛る = to serve onto a plate)","grammar:3616:ex3:points:1":"料理を盛る: to serve food","grammar:3616:ex4:trans":"I bought a new plate.","grammar:3616:ex4:structure":"〔新しい皿〕＋を＋買った。","grammar:3616:ex4:words:0:zh":"new","grammar:3616:ex4:words:0:note":"あたらしい","grammar:3616:ex4:words:0:pos":"adjective","grammar:3616:ex4:words:1:zh":"dish","grammar:3616:ex4:words:1:note":"さら","grammar:3616:ex4:words:1:pos":"noun","grammar:3616:ex4:words:2:zh":"(object marker)","grammar:3616:ex4:words:2:pos":"particle","grammar:3616:ex4:words:3:zh":"bought","grammar:3616:ex4:words:3:note":"かった","grammar:3616:ex4:words:3:pos":"verb","grammar:3616:ex4:points:0":"新しい皿: a new plate","grammar:3616:ex4:points:1":"買う: to buy","grammar:3616:ex5:trans":"Washing the dishes is a hassle.","grammar:3616:ex5:structure":"〔皿を洗う＋の〕＋が＋面倒です。 「皿を洗う」 means to wash the dishes.","grammar:3616:ex5:words:0:zh":"dish","grammar:3616:ex5:words:0:note":"さら","grammar:3616:ex5:words:0:pos":"noun","grammar:3616:ex5:words:1:zh":"(object marker)","grammar:3616:ex5:words:1:pos":"particle","grammar:3616:ex5:words:2:zh":"wash","grammar:3616:ex5:words:2:note":"dictionary form","grammar:3616:ex5:words:2:pos":"verb","grammar:3616:ex5:words:3:zh":"(nominalizer)","grammar:3616:ex5:words:3:pos":"particle","grammar:3616:ex5:words:4:zh":"(nominative)","grammar:3616:ex5:words:4:pos":"particle","grammar:3616:ex5:words:5:zh":"trouble","grammar:3616:ex5:words:5:note":"めんどう","grammar:3616:ex5:words:5:pos":"na-adjective","grammar:3616:ex5:words:6:zh":"(polite form)","grammar:3616:ex5:words:6:pos":"copula","grammar:3616:ex5:points:0":"皿を洗う: to wash the plates/bowls","grammar:3616:ex5:points:1":"面倒: troublesome, a hassle","exam:3616:zh":"I put the cake on a big, flat plate and set it on the table.","exam:3616:why":"「皿」 is a plate, which fits the description of something flat that can hold a cake. 「茶碗」 is a bowl and is usually deep, so it doesn't match 「平らな」."},"3617":{"example:3617:exzh":"There's a frog in the pond.","example:3617:exzh2":"I can hear the frogs croaking.","example:3617:exzh3":"Frogs are good at jumping.","example:3617:exzh4":"I've caught a frog before.","example:3617:exzh5":"Frogs live in damp places."},"3618":{"example:3618:exzh":"The Soviet Union was once a great power.","example:3618:exzh2":"I'm reading a history book about the Soviet Union.","example:3618:exzh3":"The Soviet Union played an important role during the Cold War.","example:3618:exzh4":"I'm interested in Soviet culture.","example:3618:exzh5":"The collapse of the Soviet Union had a huge impact."},"3620":{"example:3620:exzh":"Use radar to track aircraft.","example:3620:exzh2":"Radar can predict severe weather.","example:3620:exzh3":"Radar technology is advancing.","example:3620:exzh4":"Radar measures speed.","example:3620:exzh5":"Radar accuracy is improving."},"3622":{"example:3622:exzh":"The ending of the story moved me.","example:3622:exzh2":"The ending was unexpected.","example:3622:exzh3":"I'm looking forward to the ending of this book.","example:3622:exzh4":"The ending wasn't very clear.","example:3622:exzh5":"The ending of this movie was especially memorable."},"3623":{"example:3623:exzh":"The state of the atmosphere is changing.","example:3623:exzh2":"Air pollution is a serious problem.","example:3623:exzh3":"The air in this area is very clean.","example:3623:exzh4":"Carbon dioxide in the atmosphere is increasing.","example:3623:exzh5":"When the atmospheric pressure changes, the weather changes too."},"3624":{"example:3624:exzh":"This is the best choice.","example:3624:exzh2":"He's working toward the best possible result.","example:3624:exzh3":"I'm working under the best conditions.","example:3624:exzh4":"We strive for the best quality.","example:3624:exzh5":"She's my best friend."},"3625":{"example:3625:exzh":"Health is in good condition.","example:3625:exzh2":"This plan produced good results.","example:3625:exzh3":"His performance was good.","example:3625:exzh4":"Good communication is important.","example:3625:exzh5":"The quality of her work is good."},"3626":{"example:3626:exzh":"I play in the square at the park.","example:3626:exzh2":"There are a lot of people in the square.","example:3626:exzh3":"Events are held in the square.","example:3626:exzh4":"They arranged to meet in the square.","example:3626:exzh5":"There's a statue in the middle of the square."},"3628":{"example:3628:exzh":"He surrendered during the match.","example:3628:exzh2":"We're ready to surrender to the enemy.","example:3628:exzh3":"I chose to surrender.","example:3628:exzh4":"He had no choice but to surrender.","example:3628:exzh5":"Don't surrender—let's keep fighting."},"3629":{"example:3629:exzh":"I married him because we had a fated connection.","example:3629:exzh2":"It's important to meet people you're destined to connect with.","example:3629:exzh3":"I want to treasure this connection.","example:3629:exzh4":"I believe that if we're fated to meet, we'll see each other again.","example:3629:exzh5":"You must value the bond with your parents."},"3630":{"example:3630:exzh":"It takes time and effort, but I want to cook something delicious.","example:3630:exzh2":"This job doesn't take much effort.","example:3630:exzh3":"Don't spare any effort—give it a try.","example:3630:exzh4":"I use tools that save effort.","example:3630:exzh5":"The flower bed made with such care is beautiful."},"3631":{"example:3631:exzh":"She's my wife.","example:3631:exzh2":"There are many beautiful wives in this town.","example:3631:exzh3":"I'm getting ready for the wedding.","example:3631:exzh4":"Lately she's been fulfilling her role as a wife.","example:3631:exzh5":"She places great importance on family."},"3632":{"example:3632:exzh":"He works assisting his boss.","example:3632:exzh2":"I chose him for the supporting role.","example:3632:exzh3":"With support, the work goes more smoothly.","example:3632:exzh4":"The new project needs support staff.","example:3632:exzh5":"Being appointed as support, I feel a heavy responsibility."},"3633":{"example:3633:exzh":"Rebuilding the city is an urgent task.","example:3633:exzh2":"I took part in the reconstruction efforts after the earthquake.","example:3633:exzh3":"Rebuilding this area will take time.","example:3633:exzh4":"We're raising funds for reconstruction.","example:3633:exzh5":"The reconstruction plan has been announced."},"3634":{"example:3634:exzh":"I have to buy a ticket.","example:3634:exzh2":"This ticket has an expiration date.","example:3634:exzh3":"I accidentally lost the ticket.","example:3634:exzh4":"Please show the ticket.","example:3634:exzh5":"I'm standing in line at the ticket office.","grammar:3634:ex:trans":"I have to buy a ticket.","grammar:3634:ex:structure":"nounを＋〜なければならない。 「〜なければならない」 means must…","grammar:3634:ex:explain":"The core pattern 「〜なければならない」 means must, have no choice but to, and expresses obligation or necessity. To form it, take the nai-form of the verb (買う→買わない), drop the 「い」 and add 「ければ」, then add 「ならない」: 買わない→買わなければならない. Literally it says that if you don't do it, it won't do—in other words, you must do it. The object 「切符を」 takes 「を」. This is fairly formal, and in casual speech it is often shortened to 「買わなきゃ」. The whole sentence means have to buy a ticket. This double-negative structure for obligation trips beginners up, but a few rounds of practice will make it familiar.","grammar:3634:ex:words:0:zh":"tickets","grammar:3634:ex:words:0:note":"きっぷ","grammar:3634:ex:words:0:pos":"noun","grammar:3634:ex:words:1:zh":"(object marker)","grammar:3634:ex:words:1:pos":"particle","grammar:3634:ex:words:2:zh":"have to buy","grammar:3634:ex:words:2:note":"かわなければならない; obligation","grammar:3634:ex:words:2:pos":"verb","grammar:3634:ex:points:0":"〜なければならない: must… (obligation)","grammar:3634:ex:points:1":"買わない→買わなければ: nai-form＋なければ","grammar:3634:ex2:trans":"This ticket has an expiration date.","grammar:3634:ex2:structure":"この＋noun＋は＋nounが＋あります。","grammar:3634:ex2:words:0:zh":"this","grammar:3634:ex2:words:0:pos":"pre-noun adjectival","grammar:3634:ex2:words:1:zh":"tickets","grammar:3634:ex2:words:1:note":"きっぷ","grammar:3634:ex2:words:1:pos":"noun","grammar:3634:ex2:words:2:zh":"(topic marker)","grammar:3634:ex2:words:2:pos":"particle","grammar:3634:ex2:words:3:zh":"expiration date","grammar:3634:ex2:words:3:note":"ゆうこうきげん","grammar:3634:ex2:words:3:pos":"noun","grammar:3634:ex2:words:4:zh":"(nominative)","grammar:3634:ex2:words:4:pos":"particle","grammar:3634:ex2:words:5:zh":"there is / are","grammar:3634:ex2:words:5:note":"exists / there is","grammar:3634:ex2:words:5:pos":"verb","grammar:3634:ex2:points:0":"有効期限: expiration date","grammar:3634:ex2:points:1":"〜がある: there is …","grammar:3634:ex3:trans":"I accidentally lost the ticket.","grammar:3634:ex3:structure":"nounを＋〜てしまいました。 「〜てしまった」 expresses regret / completion.","grammar:3634:ex3:words:0:zh":"tickets","grammar:3634:ex3:words:0:note":"きっぷ","grammar:3634:ex3:words:0:pos":"noun","grammar:3634:ex3:words:1:zh":"(object marker)","grammar:3634:ex3:words:1:pos":"particle","grammar:3634:ex3:words:2:zh":"(accidentally) lost","grammar:3634:ex3:words:2:note":"なくしてしまいました；〜てしまう","grammar:3634:ex3:words:2:pos":"verb","grammar:3634:ex3:points:0":"〜てしまいました: (unfortunately / regretfully) did…","grammar:3634:ex3:points:1":"無くす: to lose, to misplace","grammar:3634:ex4:trans":"Please show the ticket.","grammar:3634:ex4:structure":"nounを＋見せてください。 「見せる」 means to show.","grammar:3634:ex4:words:0:zh":"tickets","grammar:3634:ex4:words:0:note":"きっぷ","grammar:3634:ex4:words:0:pos":"noun","grammar:3634:ex4:words:1:zh":"(object marker)","grammar:3634:ex4:words:1:pos":"particle","grammar:3634:ex4:words:2:zh":"show","grammar:3634:ex4:words:2:note":"みせて; te-form","grammar:3634:ex4:words:2:pos":"verb","grammar:3634:ex4:words:3:zh":"please","grammar:3634:ex4:words:3:note":"〜てください","grammar:3634:ex4:words:3:pos":"verb","grammar:3634:ex4:points:0":"見せる: to show (vs 見る = to see)","grammar:3634:ex4:points:1":"〜てください: please do…","grammar:3634:ex5:trans":"I'm standing in line at the ticket office.","grammar:3634:ex5:structure":"placeで＋並んでいます。 「で」 marks the place of the action. 「〜売り場」 = a place where… is sold.","grammar:3634:ex5:words:0:zh":"ticket office","grammar:3634:ex5:words:0:note":"きっぷうりば","grammar:3634:ex5:words:0:pos":"noun","grammar:3634:ex5:words:1:zh":"(place of the action)","grammar:3634:ex5:words:1:pos":"particle","grammar:3634:ex5:words:2:zh":"standing in line","grammar:3634:ex5:words:2:note":"〜ている expresses a state","grammar:3634:ex5:words:2:pos":"verb","grammar:3634:ex5:points:0":"〜売り場: a place where… is sold (切符売り場 = ticket office)","grammar:3634:ex5:points:1":"並んでいる: standing in line (a state)","exam:3634:zh":"I bought a train ticket at the station and then went to the platform.","exam:3634:why":"「電車の切符」 is the ticket you use to ride the train. 「地図」 is a map—not something that lets you ride, and it doesn't fit the phrasing here."},"3635":{"example:3635:exzh":"Since I'm going camping, I'll bring a tent.","example:3635:exzh2":"Setting up a tent is easy.","example:3635:exzh3":"It was comfortable inside the tent.","example:3635:exzh4":"Please help me put the tent away.","example:3635:exzh5":"In summer I play at the beach with a tent."},"3636":{"example:3636:exzh":"I want you to know what's good about this product.","example:3636:exzh2":"What's good about him is how straightforward he is.","example:3636:exzh3":"I'm working hard to bring out my strengths.","example:3636:exzh4":"I want to get across what's good about this restaurant.","example:3636:exzh5":"You'll understand what's good about this product once you actually use it."},"3637":{"example:3637:exzh":"I see my friends every week.","example:3637:exzh2":"I watch a movie every Friday.","example:3637:exzh3":"He plays soccer every week.","example:3637:exzh4":"It's important to build a weekly routine.","example:3637:exzh5":"Every weekend we go out as a family.","grammar:3637:ex:trans":"I meet a friend every week.","grammar:3637:ex:structure":"time、nounと＋会います。 「毎週」 expresses habitual frequency, and 「〜と会う」 means to meet with…","grammar:3637:ex:explain":"The key is 「と」 for doing something together. In 「〜と会う」, 「と」 marks the partner you meet and do the action with, so 「友達と会う」 = meet a friend. 「毎週」 is a frequency word meaning every week and expresses a habitual weekly action; this kind of time noun works as an adverb and goes at the start of the sentence without a particle. The verb 「会う」 appears in the polite form 「会います」, and together with 「毎週」 it shows a repeated habit. The whole sentence means I meet a friend every week. Note that the person you meet takes 「と」, not 「に」 (「に会う」 is also possible, but 「と」 emphasizes interacting with each other).","grammar:3637:ex:words:0:zh":"every week","grammar:3637:ex:words:0:note":"まいしゅう","grammar:3637:ex:words:0:pos":"noun","grammar:3637:ex:words:1:zh":"friend","grammar:3637:ex:words:1:note":"ともだち","grammar:3637:ex:words:1:pos":"noun","grammar:3637:ex:words:2:zh":"with","grammar:3637:ex:words:2:note":"the other person in a shared action","grammar:3637:ex:words:2:pos":"particle","grammar:3637:ex:words:3:zh":"meet","grammar:3637:ex:words:3:note":"あいます","grammar:3637:ex:words:3:pos":"verb","grammar:3637:ex:points:0":"毎週: every week","grammar:3637:ex:points:1":"〜と会う: to meet with…","grammar:3637:ex2:trans":"I watch a movie every Friday.","grammar:3637:ex2:structure":"〔毎週金曜日〕＋は＋nounを＋見ます。 「毎週金曜日」 = every Friday.","grammar:3637:ex2:words:0:zh":"every week","grammar:3637:ex2:words:0:note":"まいしゅう","grammar:3637:ex2:words:0:pos":"noun","grammar:3637:ex2:words:1:zh":"Friday","grammar:3637:ex2:words:1:note":"きんようび","grammar:3637:ex2:words:1:pos":"noun","grammar:3637:ex2:words:2:zh":"(topic marker)","grammar:3637:ex2:words:2:pos":"particle","grammar:3637:ex2:words:3:zh":"movie","grammar:3637:ex2:words:3:note":"えいが","grammar:3637:ex2:words:3:pos":"noun","grammar:3637:ex2:words:4:zh":"(object marker)","grammar:3637:ex2:words:4:pos":"particle","grammar:3637:ex2:words:5:zh":"look","grammar:3637:ex2:words:5:note":"みます","grammar:3637:ex2:words:5:pos":"verb","grammar:3637:ex2:points:0":"毎週金曜日: every Friday","grammar:3637:ex2:points:1":"映画を見る: to watch a movie","grammar:3637:ex3:trans":"He plays soccer every week.","grammar:3637:ex3:structure":"〜は＋毎週＋nounを＋しています。 「毎週」 expresses a habit.","grammar:3637:ex3:words:0:zh":"he","grammar:3637:ex3:words:0:note":"かれ","grammar:3637:ex3:words:0:pos":"pronoun","grammar:3637:ex3:words:1:zh":"(topic marker)","grammar:3637:ex3:words:1:pos":"particle","grammar:3637:ex3:words:2:zh":"every week","grammar:3637:ex3:words:2:note":"まいしゅう","grammar:3637:ex3:words:2:pos":"noun","grammar:3637:ex3:words:3:zh":"soccer","grammar:3637:ex3:words:3:note":"loanword","grammar:3637:ex3:words:3:pos":"noun","grammar:3637:ex3:words:4:zh":"(object marker)","grammar:3637:ex3:words:4:pos":"particle","grammar:3637:ex3:words:5:zh":"play / do","grammar:3637:ex3:words:5:note":"〜ている marks habit","grammar:3637:ex3:words:5:pos":"verb","grammar:3637:ex3:points:0":"毎週: every week","grammar:3637:ex3:points:1":"サッカーをする: to play soccer","grammar:3637:ex4:trans":"It's important to build a weekly routine.","grammar:3637:ex4:structure":"〔〜を作る＋こと〕＋が＋大切です。","grammar:3637:ex4:words:0:zh":"every week","grammar:3637:ex4:words:0:note":"まいしゅう","grammar:3637:ex4:words:0:pos":"noun","grammar:3637:ex4:words:1:zh":"'s","grammar:3637:ex4:words:1:pos":"particle","grammar:3637:ex4:words:2:zh":"routine","grammar:3637:ex4:words:2:note":"the loanword routine","grammar:3637:ex4:words:2:pos":"noun","grammar:3637:ex4:words:3:zh":"(object marker)","grammar:3637:ex4:words:3:pos":"particle","grammar:3637:ex4:words:4:zh":"build","grammar:3637:ex4:words:4:note":"つくる; dictionary form","grammar:3637:ex4:words:4:pos":"verb","grammar:3637:ex4:words:5:zh":"(nominalizer)","grammar:3637:ex4:words:5:pos":"noun","grammar:3637:ex4:words:6:zh":"(nominative)","grammar:3637:ex4:words:6:pos":"particle","grammar:3637:ex4:words:7:zh":"important","grammar:3637:ex4:words:7:note":"たいせつ","grammar:3637:ex4:words:7:pos":"na-adjective","grammar:3637:ex4:words:8:zh":"(polite form)","grammar:3637:ex4:words:8:pos":"copula","grammar:3637:ex4:points:0":"verb＋こと＋が大切: doing … is important","grammar:3637:ex4:points:1":"毎週のルーチン: a weekly routine","grammar:3637:ex5:trans":"We go out as a family every weekend.","grammar:3637:ex5:structure":"timeに＋〔家族で〕＋出かけます。 「家族で」 means together as a family (the whole family).","grammar:3637:ex5:words:0:zh":"every weekend","grammar:3637:ex5:words:0:note":"まいしゅうまつ","grammar:3637:ex5:words:0:pos":"noun","grammar:3637:ex5:words:1:zh":"(point in time)","grammar:3637:ex5:words:1:pos":"particle","grammar:3637:ex5:words:2:zh":"family","grammar:3637:ex5:words:2:note":"かぞく","grammar:3637:ex5:words:2:pos":"noun","grammar:3637:ex5:words:3:zh":"(as the whole …)","grammar:3637:ex5:words:3:note":"together","grammar:3637:ex5:words:3:pos":"particle","grammar:3637:ex5:words:4:zh":"go out","grammar:3637:ex5:words:4:note":"でかけます","grammar:3637:ex5:words:4:pos":"verb","grammar:3637:ex5:points:0":"〜で: as a group, all together (家族で = the whole family together)","grammar:3637:ex5:points:1":"出かける: to go out","exam:3637:zh":"I swim once a week on Sundays, so I go to the pool every week.","exam:3637:why":"「毎週」 means every week, which fits a frequency of once a week. 「毎日」 means every day, which is more often than the sentence says."},"3638":{"example:3638:exzh":"I eat lunch in the school cafeteria.","example:3638:exzh2":"This cafeteria is popular.","example:3638:exzh3":"The cafeteria has a varied menu.","example:3638:exzh4":"He eats at the cafeteria every day.","example:3638:exzh5":"The cafeteria food is cheap and tasty.","grammar:3638:ex:trans":"I eat lunch in the school cafeteria.","grammar:3638:ex:structure":"〔学校の食堂〕＋で、nounを＋食べます。 「で」 marks the place of the action.","grammar:3638:ex:explain":"The key is 「で」 marking where an action takes place. Eating happens in the cafeteria, so 「で」 marks the location: 「食堂で食べる」. This differs from 「に」 for existence: whenever a dynamic action happens somewhere, use 「で」. 「学校の食堂」 is linked with 「の」. 「昼ご飯を」 marks the object with 「を」. The sentence ends with the polite 「食べます」. The whole sentence means eat lunch in the school cafeteria. Beginners should remember: use 「で」 for where an action happens, and 「に」 for where something or someone exists.","grammar:3638:ex:words:0:zh":"school","grammar:3638:ex:words:0:note":"がっこう","grammar:3638:ex:words:0:pos":"noun","grammar:3638:ex:words:1:zh":"'s","grammar:3638:ex:words:1:pos":"particle","grammar:3638:ex:words:2:zh":"cafeteria","grammar:3638:ex:words:2:note":"しょくどう","grammar:3638:ex:words:2:pos":"noun","grammar:3638:ex:words:3:zh":"(place of the action)","grammar:3638:ex:words:3:pos":"particle","grammar:3638:ex:words:4:zh":"lunch","grammar:3638:ex:words:4:note":"ひるごはん","grammar:3638:ex:words:4:pos":"noun","grammar:3638:ex:words:5:zh":"(object marker)","grammar:3638:ex:words:5:pos":"particle","grammar:3638:ex:words:6:zh":"eat","grammar:3638:ex:words:6:note":"たべます","grammar:3638:ex:words:6:pos":"verb","grammar:3638:ex:points:0":"で: where the action happens (食堂で)","grammar:3638:ex:points:1":"昼ご飯: lunch","grammar:3638:ex2:trans":"This cafeteria is popular.","grammar:3638:ex2:structure":"この＋noun＋は＋人気があります。 「人気がある」 means to be popular.","grammar:3638:ex2:words:0:zh":"this","grammar:3638:ex2:words:0:pos":"pre-noun adjectival","grammar:3638:ex2:words:1:zh":"cafeteria","grammar:3638:ex2:words:1:note":"しょくどう","grammar:3638:ex2:words:1:pos":"noun","grammar:3638:ex2:words:2:zh":"(topic marker)","grammar:3638:ex2:words:2:pos":"particle","grammar:3638:ex2:words:3:zh":"popularity","grammar:3638:ex2:words:3:note":"にんき","grammar:3638:ex2:words:3:pos":"noun","grammar:3638:ex2:words:4:zh":"(nominative)","grammar:3638:ex2:words:4:pos":"particle","grammar:3638:ex2:words:5:zh":"there is / are","grammar:3638:ex2:words:5:note":"人気がある ＝ to be popular","grammar:3638:ex2:words:5:pos":"verb","grammar:3638:ex2:points:0":"人気がある: to be popular","grammar:3638:ex2:points:1":"この食堂: this cafeteria","grammar:3638:ex3:trans":"The cafeteria's menu is extensive.","grammar:3638:ex3:structure":"〔食堂のメニュー〕＋は＋na-adjective＋です。","grammar:3638:ex3:words:0:zh":"cafeteria","grammar:3638:ex3:words:0:note":"しょくどう","grammar:3638:ex3:words:0:pos":"noun","grammar:3638:ex3:words:1:zh":"'s","grammar:3638:ex3:words:1:pos":"particle","grammar:3638:ex3:words:2:zh":"menu","grammar:3638:ex3:words:2:note":"loanword","grammar:3638:ex3:words:2:pos":"noun","grammar:3638:ex3:words:3:zh":"(topic marker)","grammar:3638:ex3:words:3:pos":"particle","grammar:3638:ex3:words:4:zh":"abundant","grammar:3638:ex3:words:4:note":"ほうふ","grammar:3638:ex3:words:4:pos":"na-adjective","grammar:3638:ex3:words:5:zh":"(polite form)","grammar:3638:ex3:words:5:pos":"copula","grammar:3638:ex3:points:0":"豊富: abundant, rich (na-adjective)","grammar:3638:ex3:points:1":"食堂のメニュー: the cafeteria's menu","grammar:3638:ex4:trans":"He eats at the cafeteria every day.","grammar:3638:ex4:structure":"〜は＋毎日＋placeで＋食べます。 「で」 marks the place of the action.","grammar:3638:ex4:words:0:zh":"he","grammar:3638:ex4:words:0:note":"かれ","grammar:3638:ex4:words:0:pos":"pronoun","grammar:3638:ex4:words:1:zh":"(topic marker)","grammar:3638:ex4:words:1:pos":"particle","grammar:3638:ex4:words:2:zh":"every day","grammar:3638:ex4:words:2:note":"まいにち","grammar:3638:ex4:words:2:pos":"noun","grammar:3638:ex4:words:3:zh":"cafeteria","grammar:3638:ex4:words:3:note":"しょくどう","grammar:3638:ex4:words:3:pos":"noun","grammar:3638:ex4:words:4:zh":"(place of the action)","grammar:3638:ex4:words:4:pos":"particle","grammar:3638:ex4:words:5:zh":"eat","grammar:3638:ex4:words:5:note":"たべます","grammar:3638:ex4:words:5:pos":"verb","grammar:3638:ex4:points:0":"毎日: every day","grammar:3638:ex4:points:1":"で: place of the action (食堂で)","grammar:3638:ex5:trans":"The cafeteria's food is cheap and delicious.","grammar:3638:ex5:structure":"〜は＋〔i-adjective te-form〕＋i-adjective＋です。 「安くて」 uses the te-form to link two adjectives.","grammar:3638:ex5:words:0:zh":"cafeteria","grammar:3638:ex5:words:0:note":"しょくどう","grammar:3638:ex5:words:0:pos":"noun","grammar:3638:ex5:words:1:zh":"(topic marker)","grammar:3638:ex5:words:1:pos":"particle","grammar:3638:ex5:words:2:zh":"cheap (and)","grammar:3638:ex5:words:2:note":"やすくて; i-adjective te-form","grammar:3638:ex5:words:2:pos":"adjective","grammar:3638:ex5:words:3:zh":"tasty","grammar:3638:ex5:words:3:note":"おいしい","grammar:3638:ex5:words:3:pos":"adjective","grammar:3638:ex5:words:4:zh":"(polite form)","grammar:3638:ex5:words:4:pos":"copula","grammar:3638:ex5:points:0":"i-adjective te-form: 安い→安くて (cheap and…)","grammar:3638:ex5:points:1":"Linking adjectives: 安くて美味しい (cheap and delicious)","exam:3638:zh":"At lunch break, the students order curry or udon at the school cafeteria and eat.","exam:3638:why":"「食堂」 is a place that serves meals and where people eat. 「教室」 may be where students eat lunch, but you usually can't order food there."},"3639":{"example:3639:exzh":"The temperature is high today.","example:3639:exzh2":"I'll measure the temperature.","example:3639:exzh3":"What's the temperature outside?","example:3639:exzh4":"Let's lower the temperature inside.","example:3639:exzh5":"When the temperature drops, it gets cold.","grammar:3639:ex:trans":"The temperature is high today.","grammar:3639:ex:structure":"今日は、温度が＋高いです。「温度」＝ temperature.","grammar:3639:ex:explain":"This sentence practices the \"big subject + small subject\" structure: 「今日は温度が高い」＝ today (the overall topic) + the temperature (the actual subject) is high. 「今日は」 uses 「は」 to present the broad topic, and 「温度が」 uses 「が」 to point out what is really being described. This 「〜は〜が＋adjective」 pattern is a common Japanese frame for describing one property of a topic, as in 「象は鼻が長い」. The predicate 「高い」 is an i-adjective, and adding 「です」 at the end makes it polite. The whole sentence = the temperature is high today.","grammar:3639:ex:words:0:zh":"today","grammar:3639:ex:words:0:note":"きょう","grammar:3639:ex:words:0:pos":"noun","grammar:3639:ex:words:1:zh":"(topic marker)","grammar:3639:ex:words:1:pos":"particle","grammar:3639:ex:words:2:zh":"temperature","grammar:3639:ex:words:2:note":"おんど","grammar:3639:ex:words:2:pos":"noun","grammar:3639:ex:words:3:zh":"(nominative)","grammar:3639:ex:words:3:pos":"particle","grammar:3639:ex:words:4:zh":"high","grammar:3639:ex:words:4:note":"たかい","grammar:3639:ex:words:4:pos":"adjective","grammar:3639:ex:words:5:zh":"(polite form)","grammar:3639:ex:words:5:pos":"copula","grammar:3639:ex:points:0":"温度（おんど）: temperature","grammar:3639:ex:points:1":"温度が高い: the temperature is high","grammar:3639:ex2:trans":"I'll measure the temperature.","grammar:3639:ex2:structure":"温度を＋測ります。「温度を測る」＝ measure the temperature.","grammar:3639:ex2:words:0:zh":"temperature","grammar:3639:ex2:words:0:note":"おんど","grammar:3639:ex2:words:0:pos":"noun","grammar:3639:ex2:words:1:zh":"(object marker)","grammar:3639:ex2:words:1:pos":"particle","grammar:3639:ex2:words:2:zh":"measure","grammar:3639:ex2:words:2:note":"はかります","grammar:3639:ex2:words:2:pos":"verb","grammar:3639:ex2:points:0":"温度を測る: measure the temperature","grammar:3639:ex2:points:1":"測る: to measure","grammar:3639:ex3:trans":"How's the temperature outside?","grammar:3639:ex3:structure":"〔外の温度〕＋は、どうですか。「どうですか」＝ how is it?","grammar:3639:ex3:words:0:zh":"outside","grammar:3639:ex3:words:0:note":"そと","grammar:3639:ex3:words:0:pos":"noun","grammar:3639:ex3:words:1:zh":"'s","grammar:3639:ex3:words:1:pos":"particle","grammar:3639:ex3:words:2:zh":"temperature","grammar:3639:ex3:words:2:note":"おんど","grammar:3639:ex3:words:2:pos":"noun","grammar:3639:ex3:words:3:zh":"(topic marker)","grammar:3639:ex3:words:3:pos":"particle","grammar:3639:ex3:words:4:zh":"how","grammar:3639:ex3:words:4:pos":"adverb","grammar:3639:ex3:words:5:zh":"(polite form)","grammar:3639:ex3:words:5:pos":"copula","grammar:3639:ex3:words:6:zh":"(question)","grammar:3639:ex3:words:6:pos":"particle","grammar:3639:ex3:points:0":"外の温度: the temperature outside","grammar:3639:ex3:points:1":"どうですか: how is it? / what's it like?","grammar:3639:ex4:trans":"Let's lower the indoor temperature.","grammar:3639:ex4:structure":"〔室内の温度〕＋を＋下げましょう。「温度を下げる」＝ lower the temperature.","grammar:3639:ex4:words:0:zh":"indoor","grammar:3639:ex4:words:0:note":"しつない","grammar:3639:ex4:words:0:pos":"noun","grammar:3639:ex4:words:1:zh":"'s","grammar:3639:ex4:words:1:pos":"particle","grammar:3639:ex4:words:2:zh":"temperature","grammar:3639:ex4:words:2:note":"おんど","grammar:3639:ex4:words:2:pos":"noun","grammar:3639:ex4:words:3:zh":"(object marker)","grammar:3639:ex4:words:3:pos":"particle","grammar:3639:ex4:words:4:zh":"let's lower it","grammar:3639:ex4:words:4:note":"さげましょう；ましょう","grammar:3639:ex4:words:4:pos":"verb","grammar:3639:ex4:points:0":"室内の温度: indoor temperature","grammar:3639:ex4:points:1":"温度を下げる: lower the temperature","grammar:3639:ex5:trans":"When the temperature drops, it gets cold.","grammar:3639:ex5:structure":"〔温度が下がる＋と〕、寒くなります。「と」 marks a natural consequence, 「寒くなる」＝ get cold.","grammar:3639:ex5:words:0:zh":"temperature","grammar:3639:ex5:words:0:note":"おんど","grammar:3639:ex5:words:0:pos":"noun","grammar:3639:ex5:words:1:zh":"(nominative)","grammar:3639:ex5:words:1:pos":"particle","grammar:3639:ex5:words:2:zh":"go down","grammar:3639:ex5:words:2:note":"さがる; dictionary form","grammar:3639:ex5:words:2:pos":"verb","grammar:3639:ex5:words:3:zh":"(as soon as…)","grammar:3639:ex5:words:3:pos":"particle","grammar:3639:ex5:words:4:zh":"to get cold","grammar:3639:ex5:words:4:note":"〜くなる","grammar:3639:ex5:words:4:pos":"adjective","grammar:3639:ex5:points:0":"温度が下がる: the temperature drops","grammar:3639:ex5:points:1":"〜と: as soon as… / whenever… ; 寒くなる: get cold"},"3640":{"example:3640:exzh":"I'm watching a sports broadcast.","example:3640:exzh2":"What time does the broadcast start?","example:3640:exzh3":"He's doing a live radio broadcast.","example:3640:exzh4":"The live broadcast is running late.","example:3640:exzh5":"I'm enjoying the TV broadcast."},"3641":{"example:3641:exzh":"He lives as a monk.","example:3641:exzh2":"The monastery is a quiet place.","example:3641:exzh3":"She's interested in monastic practice.","example:3641:exzh4":"I went to the mountains to do ascetic training.","example:3641:exzh5":"Monastic training is a kind of spiritual discipline."},"3642":{"example:3642:exzh":"I'll tidy up the room.","example:3642:exzh2":"It's necessary to organize the materials.","example:3642:exzh3":"Let's tidy things up every day.","example:3642:exzh4":"He's organizing the documents.","example:3642:exzh5":"Getting your work in order is difficult."},"3646":{"example:3646:exzh":"His secret came out.","example:3646:exzh2":"I'm afraid the truth will come out.","example:3646:exzh3":"It'll be a problem if that gets found out.","example:3646:exzh4":"I'll make sure nobody finds out.","example:3646:exzh5":"The secret has leaked out."},"3647":{"example:3647:exzh":"The day of the exam has finally come.","example:3647:exzh2":"Summer vacation is finally starting.","example:3647:exzh3":"The preparations for the trip are finally done.","example:3647:exzh4":"The new project is finally about to start.","example:3647:exzh5":"I'm finally going to confess my feelings to her."},"3648":{"example:3648:exzh":"This system has crime-prevention measures in place.","example:3648:exzh2":"I installed a security camera.","example:3648:exzh3":"We need to raise awareness of crime prevention.","example:3648:exzh4":"A crime-prevention drill was held at the school.","example:3648:exzh5":"Please lock the door for security."},"3649":{"example:3649:exzh":"Strict measures are necessary.","example:3649:exzh2":"It's under strict surveillance.","example:3649:exzh3":"Strict security is in place.","example:3649:exzh4":"Strict safety standards are required.","example:3649:exzh5":"This information will be handled strictly."},"3650":{"example:3650:exzh":"A fly is flying around.","example:3650:exzh2":"Let's keep flies away from the food.","example:3650:exzh3":"The fly is so annoying that I can't concentrate.","example:3650:exzh4":"If you open the window, flies come in.","example:3650:exzh5":"You often see flies in summer."},"3651":{"example:3651:exzh":"Hey, what are you doing there?","example:3651:exzh2":"Hey, you mustn't do that.","example:3651:exzh3":"Hey, pay attention!","example:3651:exzh4":"Hey, answer me!","example:3651:exzh5":"Hey, study harder!"},"3652":{"example:3652:exzh":"He won the tournament.","example:3652:exzh2":"The winning prize is one million yen.","example:3652:exzh3":"The winning team advances to the next round.","example:3652:exzh4":"We're aiming to win this tournament.","example:3652:exzh5":"Don't miss the moment of victory."},"3653":{"example:3653:exzh":"The integration of companies is progressing.","example:3653:exzh2":"Integrating data is important.","example:3653:exzh3":"I think it's good for cultural integration to move forward.","example:3653:exzh4":"Efforts toward integration have begun.","example:3653:exzh5":"Integrating the education system is a difficult issue."},"3654":{"example:3654:exzh":"She's a famous actress.","example:3654:exzh2":"She's active as an actress.","example:3654:exzh3":"Many actresses appear in this film.","example:3654:exzh4":"I'm studying to become an actress.","example:3654:exzh5":"A new actress has made her debut."},"3655":{"example:3655:exzh":"He's raising an adopted child.","example:3655:exzh2":"Adoption requires legal procedures.","example:3655:exzh3":"We decided to adopt a child.","example:3655:exzh4":"She lives happily with her adopted child.","example:3655:exzh5":"Adopting a child is important."},"3656":{"example:3656:exzh":"I blew an important interview.","example:3656:exzh2":"I'm reflecting on my mistake.","example:3656:exzh3":"Don't give up just because you failed once.","example:3656:exzh4":"I checked several times so I wouldn't mess up this time.","example:3656:exzh5":"He messed up at work and got scolded badly by his boss."},"3657":{"example:3657:exzh":"This product conforms to international standards.","example:3657:exzh2":"Setting standards is important.","example:3657:exzh3":"Educational standards are improving.","example:3657:exzh4":"That company places importance on quality standards.","example:3657:exzh5":"We are expected to follow the standards."},"3658":{"example:3658:exzh":"This sentence is difficult.","example:3658:exzh2":"I like reading sentences.","example:3658:exzh3":"I'm studying the grammar of this sentence.","example:3658:exzh4":"I'm practicing writing sentences.","example:3658:exzh5":"Please translate this sentence.","grammar:3658:ex:trans":"This sentence is difficult.","grammar:3658:ex:structure":"この＋文＋は、難しいです。「文」＝ sentence, piece of writing.","grammar:3658:ex:explain":"The key noun is 「文（ぶん）」＝ sentence, passage. Note that when read ぶん it means a sentence in the grammatical sense; there is also the older reading ふみ, meaning a letter, but here it means \"sentence.\" The pattern is 「〜は〜です」, with 「は」 presenting the topic 「この文」 and the predicate being the i-adjective 「難しい」 plus the polite 「です」. 「この」 is a pre-noun adjectival meaning \"this.\" The whole sentence = this sentence is difficult. Distinguish 「文」 (a sentence) from 「文章」 (a whole piece of writing) — the scope is different: one 文 is a single sentence, while 文章 is made up of several sentences.","grammar:3658:ex:words:0:zh":"this","grammar:3658:ex:words:0:pos":"pre-noun adjectival","grammar:3658:ex:words:1:zh":"sentence","grammar:3658:ex:words:1:note":"ぶん","grammar:3658:ex:words:1:pos":"noun","grammar:3658:ex:words:2:zh":"(topic marker)","grammar:3658:ex:words:2:pos":"particle","grammar:3658:ex:words:3:zh":"difficult","grammar:3658:ex:words:3:note":"むずかしい","grammar:3658:ex:words:3:pos":"adjective","grammar:3658:ex:words:4:zh":"(polite form)","grammar:3658:ex:words:4:pos":"copula","grammar:3658:ex:points:0":"文（ぶん）: sentence, passage","grammar:3658:ex:points:1":"この文：this sentence","grammar:3658:ex2:trans":"I like reading texts.","grammar:3658:ex2:structure":"〔文を読む＋の〕＋が＋好きです。","grammar:3658:ex2:words:0:zh":"text","grammar:3658:ex2:words:0:note":"ぶん","grammar:3658:ex2:words:0:pos":"noun","grammar:3658:ex2:words:1:zh":"(object marker)","grammar:3658:ex2:words:1:pos":"particle","grammar:3658:ex2:words:2:zh":"reading","grammar:3658:ex2:words:2:note":"dictionary form","grammar:3658:ex2:words:2:pos":"verb","grammar:3658:ex2:words:3:zh":"(nominalizer)","grammar:3658:ex2:words:3:pos":"particle","grammar:3658:ex2:words:4:zh":"(object marker)","grammar:3658:ex2:words:4:pos":"particle","grammar:3658:ex2:words:5:zh":"to like","grammar:3658:ex2:words:5:note":"すき","grammar:3658:ex2:words:5:pos":"na-adjective","grammar:3658:ex2:words:6:zh":"(polite form)","grammar:3658:ex2:words:6:pos":"copula","grammar:3658:ex2:points:0":"文を読む: read sentences","grammar:3658:ex2:points:1":"verb + の + が好き: like doing…","grammar:3658:ex3:trans":"I'm studying the grammar of this sentence.","grammar:3658:ex3:structure":"〜の文法を勉強しています","grammar:3658:ex3:explain":"「この文の文法」 is the grammar used in this sentence, and the whole phrase takes 「を」 to mark it as the object of study. 「勉強する」 becomes 「勉強しています」, which shows that you're studying it now, and can also describe something you've been studying over the recent period.","grammar:3658:ex3:words:0:zh":"this","grammar:3658:ex3:words:0:pos":"pre-noun adjectival","grammar:3658:ex3:words:1:zh":"sentence","grammar:3658:ex3:words:1:note":"ぶん","grammar:3658:ex3:words:1:pos":"noun","grammar:3658:ex3:words:2:zh":"(possession / modification)","grammar:3658:ex3:words:2:pos":"particle","grammar:3658:ex3:words:3:zh":"grammar","grammar:3658:ex3:words:3:note":"ぶんぽう","grammar:3658:ex3:words:3:pos":"noun","grammar:3658:ex3:words:4:zh":"(object)","grammar:3658:ex3:words:4:pos":"particle","grammar:3658:ex3:words:5:zh":"study","grammar:3658:ex3:words:5:note":"べんきょう","grammar:3658:ex3:words:5:pos":"noun","grammar:3658:ex3:words:6:zh":"carry out","grammar:3658:ex3:words:6:pos":"verb","grammar:3658:ex3:words:7:zh":"(links to the progressive expression)","grammar:3658:ex3:words:7:pos":"particle","grammar:3658:ex3:words:8:zh":"in progress","grammar:3658:ex3:words:8:pos":"verb","grammar:3658:ex3:words:9:zh":"(polite tone)","grammar:3658:ex3:words:9:pos":"auxiliary verb","grammar:3658:ex3:points:0":"「勉強しています」 uses 「〜ている」 to show learning that is in progress or ongoing.","grammar:3658:ex3:points:1":"「この」 must be followed by a noun; here it combines with 「文」 to mean \"this sentence.\"","grammar:3658:ex4:trans":"I'm practicing writing sentences.","grammar:3658:ex4:structure":"〔文を書く〕＋練習＋を＋しています。「文を書く」 modifies 「練習」, and 「練習をする」＝ practice.","grammar:3658:ex4:words:0:zh":"sentence","grammar:3658:ex4:words:0:note":"ぶん","grammar:3658:ex4:words:0:pos":"noun","grammar:3658:ex4:words:1:zh":"(object marker)","grammar:3658:ex4:words:1:pos":"particle","grammar:3658:ex4:words:2:zh":"write","grammar:3658:ex4:words:2:note":"dictionary form modification","grammar:3658:ex4:words:2:pos":"verb","grammar:3658:ex4:words:3:zh":"practice","grammar:3658:ex4:words:3:note":"れんしゅう","grammar:3658:ex4:words:3:pos":"noun","grammar:3658:ex4:words:4:zh":"(object marker)","grammar:3658:ex4:words:4:pos":"particle","grammar:3658:ex4:words:5:zh":"do","grammar:3658:ex4:words:5:note":"練習をする；〜ている","grammar:3658:ex4:words:5:pos":"verb","grammar:3658:ex4:points:0":"文を書く: write a sentence","grammar:3658:ex4:points:1":"練習をする: practice","grammar:3658:ex5:trans":"Please translate this sentence.","grammar:3658:ex5:structure":"この＋文を＋翻訳してください。「文を翻訳する」＝ translate a sentence.","grammar:3658:ex5:words:0:zh":"this","grammar:3658:ex5:words:0:pos":"pre-noun adjectival","grammar:3658:ex5:words:1:zh":"sentence","grammar:3658:ex5:words:1:note":"ぶん","grammar:3658:ex5:words:1:pos":"noun","grammar:3658:ex5:words:2:zh":"(object marker)","grammar:3658:ex5:words:2:pos":"particle","grammar:3658:ex5:words:3:zh":"translation","grammar:3658:ex5:words:3:note":"te-form","grammar:3658:ex5:words:3:pos":"verb","grammar:3658:ex5:words:4:zh":"please","grammar:3658:ex5:words:4:note":"〜てください","grammar:3658:ex5:words:4:pos":"verb","grammar:3658:ex5:points:0":"文を翻訳する: translate a sentence","grammar:3658:ex5:points:1":"翻訳する: translate"},"3659":{"example:3659:exzh":"This alley is quiet.","example:3659:exzh2":"There's a small shop in the back alley.","example:3659:exzh3":"Let's go into the alley and take a look.","example:3659:exzh4":"Children are playing in the alley.","example:3659:exzh5":"I like walking through the alleys."},"3660":{"example:3660:exzh":"She has a quiet personality.","example:3660:exzh2":"My dog is very gentle.","example:3660:exzh3":"Many of the children are quiet.","example:3660:exzh4":"He's quiet, but he's a kind person.","example:3660:exzh5":"They stay quiet at school."},"3662":{"example:3662:exzh":"He works in the IT industry.","example:3662:exzh2":"It's important to keep up with industry news.","example:3662:exzh3":"I want to play a leading role in the industry.","example:3662:exzh4":"Experience matters in this industry.","example:3662:exzh5":"Our industry is changing rapidly."},"3663":{"example:3663:exzh":"He's still a small child.","example:3663:exzh2":"I like talking about memories from when I was little.","example:3663:exzh3":"Let's be gentle with small children.","example:3663:exzh4":"She's liked drawing since she was little.","example:3663:exzh5":"It's fun to watch young animals playing."},"3664":{"example:3664:exzh":"Success requires patience.","example:3664:exzh2":"It's important to wait patiently.","example:3664:exzh3":"He faces challenges with patience.","example:3664:exzh4":"Being patient helps you grow.","example:3664:exzh5":"Patience sometimes comes with hardship."},"3665":{"example:3665:exzh":"The company needs improvement.","example:3665:exzh2":"Please propose improvements.","example:3665:exzh3":"Let's discuss improving this issue.","example:3665:exzh4":"It's important to come up with improvement measures.","example:3665:exzh5":"By continuing to improve, you can get better results."},"3667":{"example:3667:exzh":"He's a good-for-nothing.","example:3667:exzh2":"I don't want anything to do with a good-for-nothing like that.","example:3667:exzh3":"I have a lot of good-for-nothing friends.","example:3667:exzh4":"She thinks she's a good-for-nothing.","example:3667:exzh5":"I hate living as a good-for-nothing."},"3668":{"example:3668:exzh":"She gently closed the door.","example:3668:exzh2":"She gently picked up the baby.","example:3668:exzh3":"I whispered softly in his ear.","example:3668:exzh4":"Please leave him alone for a while.","example:3668:exzh5":"He gently wiped away his tears."},"3669":{"example:3669:exzh":"The Earth attracts objects through gravity.","example:3669:exzh2":"He jumped as if ignoring gravity.","example:3669:exzh3":"Gravity is deeply tied to our daily lives.","example:3669:exzh4":"In outer space, gravity is very weak.","example:3669:exzh5":"Objects fall because of gravity."},"3671":{"example:3671:exzh":"The door slammed shut with a thud.","example:3671:exzh2":"The stone dropped with a thud and startled the people around.","example:3671:exzh3":"My heart started pounding.","example:3671:exzh4":"It felt like being hit with one heavy blow.","example:3671:exzh5":"His footsteps grew louder and louder."},"3673":{"example:3673:exzh":"He turned violent in an instant.","example:3673:exzh2":"Violent behavior is not acceptable.","example:3673:exzh3":"She felt she had been treated roughly.","example:3673:exzh4":"You shouldn't use such rough language.","example:3673:exzh5":"Reckless driving is dangerous."},"3674":{"example:3674:exzh":"Wow, what a view!","example:3674:exzh2":"Wow, that startled me!","example:3674:exzh3":"Wow, those clothes are way too cute!","example:3674:exzh4":"Wow, that smells amazing!","example:3674:exzh5":"Wow, this dish is the best!"},"3677":{"example:3677:exzh":"Gathering outside information is important.","example:3677:exzh2":"He's in charge of contact with the outside.","example:3677:exzh3":"We must value outside opinions.","example:3677:exzh4":"Sometimes we're influenced from the outside.","example:3677:exzh5":"We'll work together with people from outside."},"3678":{"example:3678:exzh":"He said he'd treat us.","example:3678:exzh2":"It's important to treat others once in a while, too.","example:3678:exzh3":"I treated a friend.","example:3678:exzh4":"Today's treat is a special one.","example:3678:exzh5":"Treating someone is a sign of generosity."},"3679":{"example:3679:exzh":"She puts on makeup every morning.","example:3679:exzh2":"Makeup matters for building confidence.","example:3679:exzh3":"He went to buy cosmetics.","example:3679:exzh4":"Please teach me how to apply makeup.","example:3679:exzh5":"I sometimes do my makeup with friends."},"3680":{"example:3680:exzh":"He left the hospital yesterday.","example:3680:exzh2":"I'm looking forward to the day I leave the hospital.","example:3680:exzh3":"The hospital's policy determined that the patient would be discharged.","example:3680:exzh4":"My friend left the hospital, so I went to visit him.","example:3680:exzh5":"Get plenty of rest after leaving the hospital.","grammar:3680:ex:trans":"He left the hospital yesterday.","grammar:3680:ex:structure":"〜は＋time＋退院しました. 「退院する」 means to leave the hospital.","grammar:3680:ex:words:0:zh":"he","grammar:3680:ex:words:0:note":"かれ","grammar:3680:ex:words:0:pos":"pronoun","grammar:3680:ex:words:1:zh":"(topic marker)","grammar:3680:ex:words:1:pos":"particle","grammar:3680:ex:words:2:zh":"yesterday","grammar:3680:ex:words:2:note":"きのう","grammar:3680:ex:words:2:pos":"noun","grammar:3680:ex:words:3:zh":"left the hospital","grammar:3680:ex:words:3:note":"たいいんしました","grammar:3680:ex:words:3:pos":"verb","grammar:3680:ex:points:0":"退院する: to leave the hospital (opposite: 入院する, to be hospitalized)","grammar:3680:ex:points:1":"昨日: yesterday","grammar:3680:ex2:trans":"I'm looking forward to the day I leave the hospital.","grammar:3680:ex2:structure":"〔退院の日〕＋を＋楽しみにしています. 「〜を楽しみにする」 means to look forward to ….","grammar:3680:ex2:words:0:zh":"leaving the hospital","grammar:3680:ex2:words:0:note":"たいいん","grammar:3680:ex2:words:0:pos":"noun","grammar:3680:ex2:words:1:zh":"'s","grammar:3680:ex2:words:1:pos":"particle","grammar:3680:ex2:words:2:zh":"day","grammar:3680:ex2:words:2:note":"ひ","grammar:3680:ex2:words:2:pos":"noun","grammar:3680:ex2:words:3:zh":"(object marker)","grammar:3680:ex2:words:3:pos":"particle","grammar:3680:ex2:words:4:zh":"looking forward to","grammar:3680:ex2:words:4:note":"〜を楽しみにする","grammar:3680:ex2:words:4:pos":"verb","grammar:3680:ex2:points:0":"〜を楽しみにする: to look forward to…","grammar:3680:ex2:points:1":"退院の日: the day of leaving the hospital","grammar:3680:ex3:trans":"The discharge was decided by the hospital's policy.","grammar:3680:ex3:structure":"〔病院の方針〕＋で、退院が＋決まりました. 「で」 marks the cause, and 「決まる」 is the intransitive verb meaning to be decided.","grammar:3680:ex3:words:0:zh":"hospital","grammar:3680:ex3:words:0:note":"びょういん","grammar:3680:ex3:words:0:pos":"noun","grammar:3680:ex3:words:1:zh":"'s","grammar:3680:ex3:words:1:pos":"particle","grammar:3680:ex3:words:2:zh":"policy","grammar:3680:ex3:words:2:note":"ほうしん","grammar:3680:ex3:words:2:pos":"noun","grammar:3680:ex3:words:3:zh":"because","grammar:3680:ex3:words:3:note":"cause / reason","grammar:3680:ex3:words:3:pos":"particle","grammar:3680:ex3:words:4:zh":"leaving the hospital","grammar:3680:ex3:words:4:note":"たいいん","grammar:3680:ex3:words:4:pos":"noun","grammar:3680:ex3:words:5:zh":"(nominative)","grammar:3680:ex3:words:5:pos":"particle","grammar:3680:ex3:words:6:zh":"decided","grammar:3680:ex3:words:6:note":"きまりました; intransitive verb","grammar:3680:ex3:words:6:pos":"verb","grammar:3680:ex3:points:0":"〜で: because of … (cause; 方針で)","grammar:3680:ex3:points:1":"決まる: (intransitive) to be decided, to be settled","grammar:3680:ex4:trans":"My friend left the hospital, so I went to visit him.","grammar:3680:ex4:structure":"〔〜が退院した〕＋ので、お見舞いに＋行きました. 「ので」 marks the cause, and 「〜に行く」 marks purpose.","grammar:3680:ex4:words:0:zh":"friend","grammar:3680:ex4:words:0:note":"ともだち","grammar:3680:ex4:words:0:pos":"noun","grammar:3680:ex4:words:1:zh":"(nominative)","grammar:3680:ex4:words:1:note":"subject of the subordinate clause","grammar:3680:ex4:words:1:pos":"particle","grammar:3680:ex4:words:2:zh":"left the hospital","grammar:3680:ex4:words:2:note":"ta-form","grammar:3680:ex4:words:2:pos":"verb","grammar:3680:ex4:words:3:zh":"because","grammar:3680:ex4:words:3:note":"cause / reason","grammar:3680:ex4:words:3:pos":"particle","grammar:3680:ex4:words:4:zh":"visit (someone who is sick)","grammar:3680:ex4:words:4:note":"おみまい","grammar:3680:ex4:words:4:pos":"noun","grammar:3680:ex4:words:5:zh":"(purpose)","grammar:3680:ex4:words:5:pos":"particle","grammar:3680:ex4:words:6:zh":"went","grammar:3680:ex4:words:6:note":"いきました","grammar:3680:ex4:words:6:pos":"verb","grammar:3680:ex4:points:0":"〜ので: because … (reason)","grammar:3680:ex4:points:1":"お見舞いに行く: to go visit someone (in the hospital)","grammar:3680:ex5:trans":"Get plenty of rest after you leave the hospital.","grammar:3680:ex5:structure":"〔退院後〕＋は、しっかり＋休んでください. 「〜後」 means after …, and 「しっかり」 means properly.","grammar:3680:ex5:words:0:zh":"leaving the hospital","grammar:3680:ex5:words:0:note":"たいいん","grammar:3680:ex5:words:0:pos":"noun","grammar:3680:ex5:words:1:zh":"later, afterwards","grammar:3680:ex5:words:1:note":"ご; 〜後 = after …","grammar:3680:ex5:words:1:pos":"noun","grammar:3680:ex5:words:2:zh":"(topic marker)","grammar:3680:ex5:words:2:pos":"particle","grammar:3680:ex5:words:3:zh":"well","grammar:3680:ex5:words:3:pos":"adverb","grammar:3680:ex5:words:4:zh":"rest","grammar:3680:ex5:words:4:note":"やすんで; te-form","grammar:3680:ex5:words:4:pos":"verb","grammar:3680:ex5:words:5:zh":"please","grammar:3680:ex5:words:5:note":"〜てください","grammar:3680:ex5:words:5:pos":"verb","grammar:3680:ex5:points:0":"〜後（ご）: after … (退院後 = after leaving the hospital)","grammar:3680:ex5:points:1":"しっかり: properly, thoroughly"},"3681":{"example:3681:exzh":"This bus runs on a dedicated route.","example:3681:exzh2":"Please use the designated road.","example:3681:exzh3":"A dedicated parking lot is needed.","example:3681:exzh4":"His room is a private space.","example:3681:exzh5":"You can download the dedicated app."},"3682":{"example:3682:exzh":"He comes from a noble family.","example:3682:exzh2":"The aristocracy is a thing of the past.","example:3682:exzh3":"Nobles live differently from ordinary people.","example:3682:exzh4":"There's a nobleman's mansion in this town.","example:3682:exzh5":"I learned about aristocratic culture."},"3683":{"example:3683:exzh":"She lives in the suburbs.","example:3683:exzh2":"The suburbs are quiet.","example:3683:exzh3":"I'm planning to go out to the suburbs for fun.","example:3683:exzh4":"The scenery in the suburbs is beautiful.","example:3683:exzh5":"A new shopping mall opened in the suburbs."},"3684":{"example:3684:exzh":"The goat is eating grass.","example:3684:exzh2":"Goats are very cute.","example:3684:exzh3":"She keeps a goat.","example:3684:exzh4":"Goat's milk is delicious.","example:3684:exzh5":"The goat is climbing the mountain."},"3686":{"example:3686:exzh":"He broke a rib.","example:3686:exzh2":"Ribs are an important part of the human body.","example:3686:exzh3":"She complained of pain in her ribs.","example:3686:exzh4":"The ribs play a part in breathing.","example:3686:exzh5":"A rib is bent."},"3687":{"example:3687:exzh":"That species is dying out.","example:3687:exzh2":"I'm worried about the loss of culture.","example:3687:exzh3":"This company has disappeared.","example:3687:exzh4":"We face the threat of extinction.","example:3687:exzh5":"The extinction of animals is a serious problem."},"3688":{"example:3688:exzh":"I love her laugh.","example:3688:exzh2":"You can hear laughter.","example:3688:exzh3":"That movie is full of laughter.","example:3688:exzh4":"Laughter eases the mood in the room.","example:3688:exzh5":"He let out a laugh."},"3689":{"example:3689:exzh":"I brush my teeth every day.","example:3689:exzh2":"I like polishing shoes.","example:3689:exzh3":"I need to sand the board.","example:3689:exzh4":"He's sharpening his sword.","example:3689:exzh5":"I'll work hard to hone this skill.","grammar:3689:ex:trans":"I brush my teeth every day.","grammar:3689:ex:structure":"I brush my teeth every day.","grammar:3689:ex:explain":"The key point is the transitive verb 「磨く（みがく）」 = to brush, scrub, polish; it also extends to 'to hone (a skill, a talent)'. Here 「歯を磨く」 = to brush one's teeth, with the object marked by 「を」. The 「〜ている」 ending expresses habit: 「毎日…磨いています」 does not mean you are brushing right now, but describes an action repeated every day — this is the 'repeated habit' use of ている. 「磨く」 is a godan (u-) verb, and its te-form uses the カ-row i-onbin sound change (く→いて). The whole sentence = I brush my teeth every day. Besides ongoing action and states, 「〜ている」 with a time adverb can also express habit.","grammar:3689:ex:words:0:zh":"every day","grammar:3689:ex:words:0:note":"まいにち","grammar:3689:ex:words:0:pos":"adverb","grammar:3689:ex:words:1:zh":"tooth","grammar:3689:ex:words:1:note":"は","grammar:3689:ex:words:1:pos":"noun","grammar:3689:ex:words:2:zh":"(object marker)","grammar:3689:ex:words:2:pos":"particle","grammar:3689:ex:words:3:zh":"brush","grammar:3689:ex:words:3:note":"みがいています","grammar:3689:ex:words:3:pos":"verb","grammar:3689:ex:points:0":"❗磨く（みがく）: ① to brush, scrub, polish (歯を磨く = brush one's teeth, 靴を磨く = polish shoes); ② to hone, refine (技を磨く) (transitive verb).","grammar:3689:ex:points:1":"磨く: to brush / scrub / hone.","grammar:3689:ex2:trans":"I like polishing shoes.","grammar:3689:ex2:structure":"I like polishing shoes.","grammar:3689:ex2:words:0:zh":"shoes","grammar:3689:ex2:words:0:note":"くつ","grammar:3689:ex2:words:0:pos":"noun","grammar:3689:ex2:words:1:zh":"(object marker)","grammar:3689:ex2:words:1:pos":"particle","grammar:3689:ex2:words:2:zh":"rub","grammar:3689:ex2:words:2:note":"みがく","grammar:3689:ex2:words:2:pos":"verb","grammar:3689:ex2:words:3:zh":"(nominalizer)","grammar:3689:ex2:words:3:pos":"particle","grammar:3689:ex2:words:4:zh":"(object)","grammar:3689:ex2:words:4:pos":"particle","grammar:3689:ex2:words:5:zh":"to like","grammar:3689:ex2:words:5:note":"すき","grammar:3689:ex2:words:5:pos":"na-adjective","grammar:3689:ex2:words:6:zh":"(polite form)","grammar:3689:ex2:words:6:pos":"copula","grammar:3689:ex2:points:0":"❗靴を磨く: to polish shoes, to shine leather shoes.","grammar:3689:ex2:points:1":"靴を磨く: to polish shoes.","grammar:3689:ex3:trans":"The board needs sanding.","grammar:3689:ex3:structure":"The board needs sanding.","grammar:3689:ex3:words:0:zh":"board","grammar:3689:ex3:words:0:note":"いた","grammar:3689:ex3:words:0:pos":"noun","grammar:3689:ex3:words:1:zh":"(object marker)","grammar:3689:ex3:words:1:pos":"particle","grammar:3689:ex3:words:2:zh":"sharpen","grammar:3689:ex3:words:2:note":"みがく","grammar:3689:ex3:words:2:pos":"verb","grammar:3689:ex3:words:3:zh":"necessary","grammar:3689:ex3:words:3:note":"ひつよう","grammar:3689:ex3:words:3:pos":"noun","grammar:3689:ex3:words:4:zh":"(nominative)","grammar:3689:ex3:words:4:pos":"particle","grammar:3689:ex3:words:5:zh":"there is / are","grammar:3689:ex3:words:5:pos":"verb","grammar:3689:ex3:points:0":"❗板を磨く: to sand a board.","grammar:3689:ex3:points:1":"板を磨く: to sand a board.","grammar:3689:ex4:trans":"He is sharpening his blade.","grammar:3689:ex4:structure":"He is sharpening his blade.","grammar:3689:ex4:words:0:zh":"he","grammar:3689:ex4:words:0:note":"かれ","grammar:3689:ex4:words:0:pos":"pronoun","grammar:3689:ex4:words:1:zh":"(topic)","grammar:3689:ex4:words:1:pos":"particle","grammar:3689:ex4:words:2:zh":"knife","grammar:3689:ex4:words:2:note":"かたな","grammar:3689:ex4:words:2:pos":"noun","grammar:3689:ex4:words:3:zh":"(object marker)","grammar:3689:ex4:words:3:pos":"particle","grammar:3689:ex4:words:4:zh":"sharpen","grammar:3689:ex4:words:4:note":"みがいている","grammar:3689:ex4:words:4:pos":"verb","grammar:3689:ex4:points:0":"❗刀を磨く: to sharpen a blade, to polish a sword blade.","grammar:3689:ex4:points:1":"刀を磨く: to sharpen a blade.","grammar:3689:ex5:trans":"I'll work hard to hone this skill.","grammar:3689:ex5:structure":"I'll work hard to hone this skill.","grammar:3689:ex5:words:0:zh":"this","grammar:3689:ex5:words:0:pos":"pre-noun adjectival","grammar:3689:ex5:words:1:zh":"technology","grammar:3689:ex5:words:1:note":"ぎじゅつ","grammar:3689:ex5:words:1:pos":"noun","grammar:3689:ex5:words:2:zh":"(object marker)","grammar:3689:ex5:words:2:pos":"particle","grammar:3689:ex5:words:3:zh":"hone","grammar:3689:ex5:words:3:note":"みがく","grammar:3689:ex5:words:3:pos":"verb","grammar:3689:ex5:words:4:zh":"for the sake of","grammar:3689:ex5:words:4:pos":"noun","grammar:3689:ex5:words:5:zh":"(purpose)","grammar:3689:ex5:words:5:pos":"particle","grammar:3689:ex5:words:6:zh":"effort","grammar:3689:ex5:words:6:note":"どりょくします","grammar:3689:ex5:words:6:pos":"verb","grammar:3689:ex5:points:0":"❗技術を磨く: to hone one's skills (sense ②, to refine).","grammar:3689:ex5:points:1":"技術を磨く: to hone one's skills."},"3690":{"example:3690:exzh":"Human organs are complex.","example:3690:exzh2":"Organ transplants are difficult surgery.","example:3690:exzh3":"It's important to keep your organs healthy.","example:3690:exzh4":"He's studying how organs function.","example:3690:exzh5":"Organs are essential to the human body."},"3692":{"example:3692:exzh":"This palace is very beautiful.","example:3692:exzh2":"Many tourists come to visit the palace.","example:3692:exzh3":"He likes historic palaces.","example:3692:exzh4":"I traveled to see the palace.","example:3692:exzh5":"The inside of the palace is gorgeous."},"3693":{"example:3693:exzh":"I need to face him and have a serious talk.","example:3693:exzh2":"It's important to face problems head-on.","example:3693:exzh3":"We should face it seriously.","example:3693:exzh4":"It takes courage to face it.","example:3693:exzh5":"Let's talk it over face to face."},"3694":{"example:3694:exzh":"This is a situation where lives need saving.","example:3694:exzh2":"He's drowning, so he needs to be saved.","example:3694:exzh3":"I heard a cry for help.","example:3694:exzh4":"Please send a signal for help.","example:3694:exzh5":"We will support lifesaving efforts."},"3695":{"example:3695:exzh":"I'm going to see an opera tonight.","example:3695:exzh2":"She loves opera.","example:3695:exzh3":"Opera is an art form that combines music and acting.","example:3695:exzh4":"Watching opera moves me.","example:3695:exzh5":"I booked tickets for the opera."},"3696":{"example:3696:exzh":"Government corruption is seen as a problem.","example:3696:exzh2":"Rotten food is dangerous.","example:3696:exzh3":"Action is needed to stop the corruption of society.","example:3696:exzh4":"Corruption has a negative impact on the economy.","example:3696:exzh5":"Let's fix the corrupt system."},"3697":{"example:3697:exzh":"There's an event to promote a new product.","example:3697:exzh2":"His company is stepping up its promotion.","example:3697:exzh3":"I saw a movie ad on TV.","example:3697:exzh4":"Online advertising really helps with promotion.","example:3697:exzh5":"Measuring the effect of promotion is important."},"3698":{"example:3698:exzh":"Kids like playing with toys.","example:3698:exzh2":"I bought him a new toy.","example:3698:exzh3":"I was looking forward to going to the toy store.","example:3698:exzh4":"I helped tidy up the toys.","example:3698:exzh5":"I broke the toy.","grammar:3698:ex:trans":"Kids like playing with toys.","grammar:3698:ex:structure":"〜は＋〔nounで遊ぶ＋の〕＋が＋好きです. 「〜で遊ぶ」 means to play with ….","grammar:3698:ex:explain":"Two key points here. First, 「〜で遊ぶ」: here 「で」 marks the means or tool of play — playing with toys. Second, nominalizing a verb with 「〜のが好き」: the verb's noun-modifying form 「遊ぶ」 plus the formal noun 「の」 turns the action into a noun, and 「が」 then marks it as what is liked — liking to play. 「子供は」 sets the topic. The whole sentence means kids like playing with toys. 「〜のが好き」 is the core pattern for saying you like doing something; here 「の」 wraps the action up into a noun.","grammar:3698:ex:words:0:zh":"child","grammar:3698:ex:words:0:note":"こども","grammar:3698:ex:words:0:pos":"noun","grammar:3698:ex:words:1:zh":"(topic marker)","grammar:3698:ex:words:1:pos":"particle","grammar:3698:ex:words:2:zh":"toy","grammar:3698:ex:words:2:pos":"noun","grammar:3698:ex:words:3:zh":"use","grammar:3698:ex:words:3:note":"means / tool","grammar:3698:ex:words:3:pos":"particle","grammar:3698:ex:words:4:zh":"hang out","grammar:3698:ex:words:4:note":"あそぶ; dictionary form","grammar:3698:ex:words:4:pos":"verb","grammar:3698:ex:words:5:zh":"(nominalizer)","grammar:3698:ex:words:5:pos":"particle","grammar:3698:ex:words:6:zh":"(object marker)","grammar:3698:ex:words:6:pos":"particle","grammar:3698:ex:words:7:zh":"to like","grammar:3698:ex:words:7:note":"すき","grammar:3698:ex:words:7:pos":"na-adjective","grammar:3698:ex:words:8:zh":"(polite form)","grammar:3698:ex:words:8:pos":"copula","grammar:3698:ex:points:0":"〜で遊ぶ: to play with … (おもちゃで遊ぶ = to play with toys)","grammar:3698:ex:points:1":"verb + の + が好き: like doing…","grammar:3698:ex2:trans":"I bought him a new toy.","grammar:3698:ex2:structure":"i-adjective＋nounを＋〜てあげました. 「〜てあげる」 shows doing something for someone as a favor.","grammar:3698:ex2:words:0:zh":"new","grammar:3698:ex2:words:0:note":"あたらしい","grammar:3698:ex2:words:0:pos":"adjective","grammar:3698:ex2:words:1:zh":"toy","grammar:3698:ex2:words:1:pos":"noun","grammar:3698:ex2:words:2:zh":"(object marker)","grammar:3698:ex2:words:2:pos":"particle","grammar:3698:ex2:words:3:zh":"bought (for someone)","grammar:3698:ex2:words:3:note":"〜てあげる: doing a favor","grammar:3698:ex2:words:3:pos":"verb","grammar:3698:ex2:points:0":"〜てあげる: (I) do … for someone else (買ってあげる = to buy something for them)","grammar:3698:ex2:points:1":"favor-giving: てあげる","grammar:3698:ex3:trans":"I was looking forward to going to the toy store.","grammar:3698:ex3:structure":"〔〜へ行く＋の〕＋が＋楽しみでした. 「〜のが楽しみ」 means to look forward to doing ….","grammar:3698:ex3:words:0:zh":"toy store","grammar:3698:ex3:words:0:note":"おもちゃや","grammar:3698:ex3:words:0:pos":"noun","grammar:3698:ex3:words:1:zh":"to","grammar:3698:ex3:words:1:note":"direction","grammar:3698:ex3:words:1:pos":"particle","grammar:3698:ex3:words:2:zh":"go","grammar:3698:ex3:words:2:note":"いく；dictionary form","grammar:3698:ex3:words:2:pos":"verb","grammar:3698:ex3:words:3:zh":"(nominalizer)","grammar:3698:ex3:words:3:pos":"particle","grammar:3698:ex3:words:4:zh":"(nominative)","grammar:3698:ex3:words:4:pos":"particle","grammar:3698:ex3:words:5:zh":"look forward to","grammar:3698:ex3:words:5:note":"たのしみ","grammar:3698:ex3:words:5:pos":"noun","grammar:3698:ex3:words:6:zh":"(past) was","grammar:3698:ex3:words:6:pos":"copula","grammar:3698:ex3:points:0":"〜屋: a … shop (おもちゃ屋 = toy store)","grammar:3698:ex3:points:1":"〜のが楽しみ: to look forward to doing …","grammar:3698:ex4:trans":"I helped tidy up the toys.","grammar:3698:ex4:structure":"〔〜を整理する＋の〕＋を＋手伝いました. 「〜のを手伝う」 means to help with doing ….","grammar:3698:ex4:words:0:zh":"toy","grammar:3698:ex4:words:0:pos":"noun","grammar:3698:ex4:words:1:zh":"(object marker)","grammar:3698:ex4:words:1:pos":"particle","grammar:3698:ex4:words:2:zh":"organize","grammar:3698:ex4:words:2:note":"せいりする; dictionary form","grammar:3698:ex4:words:2:pos":"verb","grammar:3698:ex4:words:3:zh":"(nominalizer)","grammar:3698:ex4:words:3:pos":"particle","grammar:3698:ex4:words:4:zh":"(object marker)","grammar:3698:ex4:words:4:pos":"particle","grammar:3698:ex4:words:5:zh":"helped","grammar:3698:ex4:words:5:note":"てつだいました","grammar:3698:ex4:words:5:pos":"verb","grammar:3698:ex4:points:0":"〜のを手伝う: help (do) …","grammar:3698:ex4:points:1":"整理する: to tidy up","grammar:3698:ex5:trans":"I broke the toy.","grammar:3698:ex5:structure":"nounを＋〜てしまった. 「壊す」 is the transitive verb meaning to break, and 「〜てしまった」 shows regret.","grammar:3698:ex5:words:0:zh":"toy","grammar:3698:ex5:words:0:pos":"noun","grammar:3698:ex5:words:1:zh":"(object marker)","grammar:3698:ex5:words:1:pos":"particle","grammar:3698:ex5:words:2:zh":"broke (by accident)","grammar:3698:ex5:words:2:note":"こわしてしまった；〜てしまう","grammar:3698:ex5:words:2:pos":"verb","grammar:3698:ex5:points:0":"壊す: (transitive) to break (vs 壊れる, intransitive)","grammar:3698:ex5:points:1":"〜てしまった: (accidentally / regretfully) ended up doing ..."},"3699":{"example:3699:exzh":"It's not good to hate him.","example:3699:exzh2":"Resentment has a bad effect on the heart.","example:3699:exzh3":"There's no need to resent the past.","example:3699:exzh4":"Let's talk about what we resent.","example:3699:exzh5":"I can't hate her."}};